package com.garagedesk.controller; import com.garagedesk.entity.JobStatus; import com.garagedesk.repo.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/dashboard") public class DashboardController{final JobCardRepository j;final MechanicRepository m;final ServiceBayRepository b;public DashboardController(JobCardRepository j,MechanicRepository m,ServiceBayRepository b){this.j=j;this.m=m;this.b=b;}@GetMapping public Map<String,Object> get(){return Map.of("totalJobs",j.count(),"waiting",j.countByStatus(JobStatus.WAITING),"inProgress",j.countByStatus(JobStatus.IN_PROGRESS),"qualityCheck",j.countByStatus(JobStatus.QUALITY_CHECK),"completed",j.countByStatus(JobStatus.COMPLETED),"activeBays",b.findAll().stream().filter(x->x.isActive()).count(),"availableMechanics",m.findAll().stream().filter(x->x.isAvailable()).count());}}
